// VALIDATE INPUT
const b = $input.first().json.body || $input.first().json;
if (!b.siteId) throw new Error('Missing siteId');
if (!b.message) throw new Error('Missing message');

return [{
  json: {
    siteId: b.siteId,
    conversationId: b.conversationId || null,
    userId: b.userId || 'anon',
    message: b.message.trim(),
    requestId: 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    executionId: $execution.id,
    images: b.images || (b.image ? [b.image] : []),
    executorMode: b.executorMode || 'auto'
  }
}];

// BUILD CONTEXT
const inp = $('Validate Input').item.json;
const rawSite = $input.first().json;
let site = Array.isArray(rawSite) ? rawSite[0] : (rawSite?.id ? rawSite : rawSite?.data?.[0]);
if (!site?.id) throw new Error('Site not found');

const SYSTEM_GITHUB_TOKEN = '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';
let githubToken = (site.access_token && site.access_token.trim()) || SYSTEM_GITHUB_TOKEN;

const repoMatch = (site.repo_url || '').match(/github\.com\/([^/]+)\/([^/]+)/);
if (!repoMatch) throw new Error('Invalid GitHub repo URL');

return [{
  json: {
    ...inp,
    site: { id: site.site_key || inp.siteId, uuid: site.id, name: site.name, repo_url: site.repo_url, branch: site.default_branch || 'main' },
    owner: repoMatch[1],
    repo: repoMatch[2].replace(/\.git$/, ''),
    branch: site.default_branch || 'main',
    previewUrl: 'https://' + (site.site_key || inp.siteId) + '.preview.automatelb.com',
    githubToken
  }
}];

// ENSURE WORKSPACE EXISTS
const ctx = $input.item.json;
const siteId = ctx.site?.id;
const githubToken = ctx.githubToken;
const repoUrl = ctx.site?.repo_url;

if (!siteId) {
  console.log('⚠️ No siteId, skipping workspace setup');
  return [{ json: ctx }];
}

try {
  // Check if workspace exists
  const status = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://preview-orchestrator.fly.dev/preview/status/' + siteId,
    timeout: 3000,
    json: true,
    ignoreHttpStatusErrors: true
  });

  // If not running, start it (this clones the repo)
  if (!status || status.status !== 'running') {
    console.log('🔧 Workspace not found, cloning repo...');
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://preview-orchestrator.fly.dev/preview/start',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ siteId, repoUrl, gitToken: githubToken }),
      timeout: 30000,
      ignoreHttpStatusErrors: true
    });
    await new Promise(r => setTimeout(r, 2000)); // Wait for clone
    console.log('✅ Workspace ready');
  } else {
    console.log('✅ Workspace already running');
  }
} catch (e) {
  console.error('⚠️ Workspace setup error:', e.message);
}

return [{ json: ctx }];

// AGENT 1: INTENT CLASSIFIER (OpenRouter Gemini)
const ctx = $input.item.json;
const msg = ctx.message || '';
const msgLower = (msg || '').toLowerCase();

// FAST PATH: Regex-based classification
const SIMPLE_EDIT = [
  /^(change|update|set|fix|replace|modify)\s+(the\s+)?(title|text|heading|name|color|background|font|size|padding|margin)/i,
  /^make\s+(it|the|this)\s+(bigger|smaller|larger|bolder|darker|lighter|centered)/i,
  /^(remove|delete|hide)\s+(the\s+)?\w{2,20}$/i,
  /^(add|put|insert)\s+(a\s+)?(comma|period|space|word)/i
];

const QUESTIONS = [
  /^(what|why|how|can you|could you|should|is it|explain|describe|tell me|where|when|who)/i,
  /^(do you|does it|have you|will it)/i,
  /\?\s*$/
];

const COMPLEX_KEYWORDS = ['implement', 'create', 'build', 'add feature', 'new page', 'new component', 'integrate', 'api', 'database', 'authentication', 'form with', 'multiple'];

const isSimple = SIMPLE_EDIT.some(p => p.test(msg));
const isQuestion = QUESTIONS.some(p => p.test(msg));
const hasComplexKeyword = COMPLEX_KEYWORDS.some(k => msgLower.includes(k));

if (isQuestion && !hasComplexKeyword) {
  return [{ json: { ...ctx, intent: { type: 'question', confidence: 0.9, needsPlanner: false, source: 'regex' } } }];
}
if (isSimple && !hasComplexKeyword) {
  return [{ json: { ...ctx, intent: { type: 'simple_edit', confidence: 0.9, needsPlanner: false, source: 'regex' } } }];
}
if (hasComplexKeyword) {
  return [{ json: { ...ctx, intent: { type: 'complex_feature', confidence: 0.85, needsPlanner: true, source: 'regex' } } }];
}

// SLOW PATH: API Method (OpenRouter)
console.log('🤔 Ambiguous request, calling Gemini via OpenRouter...');
const OPENROUTER_KEY = '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';

try {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { 
      'Authorization': 'Bearer ' + OPENROUTER_KEY,
      'HTTP-Referer': 'https://n8n.io',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'google/gemini-3-flash-preview',
      messages: [{ role: 'user', content: 'Classify this request: "' + msg.substring(0, 300) + '"\n\nRespond ONLY with JSON: {\"type\":\"simple_edit|complex_feature|question|clarification\",\"confidence\":0.X}' }],
      response_format: { type: 'json_object' }
    }),
    timeout: 10000,
    json: true
  });

  const text = r.choices?.[0]?.message?.content || '{}';
  const intent = JSON.parse(text.match(/\{[^}]+\}/)?.[0] || '{\"type\":\"simple_edit\",\"confidence\":0.5}');
  intent.needsPlanner = intent.type === 'complex_feature' || intent.confidence < 0.7;
  intent.source = 'gemini-openrouter';

  return [{ json: { ...ctx, intent } }];
} catch (e) {
  console.error('Gemini error:', e.message);
  return [{ json: { ...ctx, intent: { type: 'simple_edit', confidence: 0.5, needsPlanner: true, source: 'fallback' } } }];
}

// FETCH MEMORY - Query messages table for conversation history
const ctx = $input.item.json;
const siteId = ctx.site?.uuid;
const requestId = ctx.requestId || 'unknown';
const conversationId = ctx.conversationId || null;

// Insert initial thinking step
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({
