      step_number: 1,
      tool_name: 'analyze',
      status: 'running',
      message: 'Analyzing request...',
      details: { message: ctx.message?.substring(0, 100) }
    }),
    timeout: 5000
  });
} catch (e) { console.log('Initial thinking step error:', e.message); }

// If no conversationId, return empty context
if (!conversationId) {
  console.log('📝 No conversationId, starting fresh');
  return [{ json: { ...ctx, memoryContext: 'First request - no conversation history.' } }];
}

try {
  // Query messages table directly using session_id (conversationId)
  const messagesUrl = 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/messages?session_id=eq.' + conversationId + '&order=created_at.desc&limit=10';

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: messagesUrl,
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4'
    },
    timeout: 10000
  });

  let memoryContext = 'First request in session.';
  if (Array.isArray(response) && response.length > 0) {
    // Reverse to get chronological order (oldest first)
    const messages = response.reverse();
    memoryContext = 'Recent conversation:\n' + messages.map(m => {
      const role = m.role === 'user' ? 'User' : 'Assistant';
      const content = (m.content || '').slice(0, 150);
      const meta = m.metadata || {};
      const files = (meta.filesModified || meta.filesCreated || meta.filesChanged || []).map(f => f.split('/').pop()).join(', ');
      if (files) {
        return '- ' + role + ': ' + content + ' [Files: ' + files + ']';
      }
      return '- ' + role + ': ' + content;
    }).join('\n');
  }

  console.log('📝 Memory loaded from messages:', response.length || 0, 'messages');
  return [{ json: { ...ctx, memoryContext } }];
} catch (e) {
  console.error('Memory fetch error:', e.message);
  return [{ json: { ...ctx, memoryContext: 'First request.' } }];
}

// QUESTION RESPONDER (OpenRouter - Gemini)
const ctx = $input.item.json;
const OPENROUTER_KEY = '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';
const siteId = ctx.site?.id;
const memoryContext = ctx.memoryContext || 'No prior context.';
const MODEL = 'google/gemini-3-flash-preview';

const TOOLS = [
  { type: 'function', function: { name: 'list_files', description: 'List files matching a glob pattern', parameters: { type: 'object', properties: { pattern: { type: 'string' } }, required: ['pattern'] } } },
  { type: 'function', function: { name: 'grep_search', description: 'Search for text inside files', parameters: { type: 'object', properties: { pattern: { type: 'string' } }, required: ['pattern'] } } },
  { type: 'function', function: { name: 'read_file', description: 'Read file content', parameters: { type: 'object', properties: { path: { type: 'string' }, required: ['path'] } } } }
];

const runTool = async (name, input) => {
  if (!siteId) return 'No project selected';
  const headers = { 'Content-Type': 'application/json' };
  const opts = { json: true, ignoreHttpStatusErrors: true };
  try {
    if (name === 'list_files') {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/search', headers, body: JSON.stringify({ siteId, pattern: input.pattern || '**/*', type: 'glob' }), ...opts });
      return (r?.matches || []).slice(0, 30).join('\n') || 'No files found';
    }
    if (name === 'grep_search') {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/search', headers, body: JSON.stringify({ siteId, pattern: input.pattern, type: 'grep' }), ...opts });
      return (r?.matches || []).slice(0, 20).join('\n') || 'No matches found';
    }
    if (name === 'read_file') {
      const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/read', headers, body: JSON.stringify({ siteId, filePath: input.path }), ...opts });
      return r?.content ? r.content.slice(0, 4000) : 'File not found';
    }
  } catch (e) { return 'Error: ' + e.message; }
  return 'Unknown tool';
};

try {
  let messages = [
    { role: 'system', content: 'You are a helpful web development assistant with access to the project codebase.' },
    { role: 'user', content: `Conversation history:\n${memoryContext}\n\nQuestion: ${ctx.message}` }
  ];
  let output = '';

  for (let i = 0; i < 4; i++) {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: { 'Authorization': 'Bearer ' + OPENROUTER_KEY, 'Content-Type': 'application/json', 'HTTP-Referer': 'https://n8n.io' },
      body: JSON.stringify({ model: MODEL, messages, tools: siteId ? TOOLS : undefined, temperature: 0.7 }),
      timeout: 30000, json: true
    });

    // httpRequest with json:true returns body directly
    const choice = r.choices?.[0];
    const message = choice?.message;
    if (!message) break;

    messages.push(message);

    if (message.tool_calls && message.tool_calls.length > 0) {
      for (const tc of message.tool_calls) {
        let args = {};
        try { args = JSON.parse(tc.function.arguments); } catch(e) {}
        const res = await runTool(tc.function.name, args);
        messages.push({ role: 'tool', tool_call_id: tc.id, content: res });
      }
    } else {
      output = message.content || 'Done';
      break;
    }
  }

  console.log('💬 Question answered');
  return [{ json: { ...ctx, output, isDirectResponse: true, filesModified: [], iterations: 0 } }];
} catch (e) {
  console.error('Question error:', e.message);
  return [{ json: { ...ctx, output: 'Error: ' + e.message, isDirectResponse: true, iterations: 0 } }];
}

// CLARIFICATION RESPONDER
const ctx = $input.item.json;
return [{ json: { ...ctx, output: 'Could you be more specific? Example: "Change the title to X" or "Add a button that does Y".', isDirectResponse: true, filesModified: [], filesCreated: [], filesDeleted: [], toolsUsed: [], iterations: 0 } }];

// AGENT 2: PLANNER - OPTIMIZED (Claude Sonnet 4.5)
// Groups files into logical batches instead of individual tasks
const ctx = $input.item.json;
const ANTHROPIC_KEY = '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';
const MODEL = 'claude-sonnet-4-5-20250929';

console.log('🧠 Planner (Optimized) active for:', ctx.message);

const TOOLS = [
  { name: 'list_files_glob', description: 'List files matching a glob pattern', input_schema: { type: 'object', properties: { pattern: { type: 'string' } }, required: ['pattern'] } },
  { name: 'read_file', description: 'Read file content', input_schema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } },
  { name: 'finish_plan', description: 'Output the final execution plan with GROUPED tasks', input_schema: { 
    type: 'object', 
    properties: { 
      summary: { type: 'string', description: 'Human-readable summary of what will be built' }, 
      tasks: { 
        type: 'array', 
        description: 'Array of GROUPED tasks - group related files together, max 5 tasks total', 
        items: { 
          type: 'object', 
          properties: { 
            id: { type: 'number' }, 
            type: { type: 'string', enum: ['create_batch', 'modify_batch'], description: 'Task type - use batch operations' }, 
            files: { type: 'array', items: { type: 'string' }, description: 'List of files in this batch' },
            description: { type: 'string', description: 'What to do for all files in the batch' }
          }, 
          required: ['id', 'type', 'files', 'description'] 
        } 
      }, 
      complexity: { type: 'string', enum: ['low', 'medium', 'high'] } 
    }, 
    required: ['summary', 'tasks', 'complexity'] 
  }}
];

const runTool = async (name, args) => {
  // For WebContainer mode, we don't need to read files - just return guidance
  if (name === 'list_files_glob') {
    return 'No files yet - this is a new project in WebContainer.';
  }
  if (name === 'read_file') {
    return 'File does not exist - create it with the executor.';
  }
  return 'Unknown tool';
};

const SYSTEM = `You are a Senior Dev Planner. Create a CONCISE execution plan with GROUPED tasks.

IMPORTANT RULES:
1. Group related files into BATCH tasks (max 5 tasks total)
2. For new projects, use this grouping:
   - Task 1: Config files (package.json, tsconfig.json, next.config.js, tailwind.config.ts, postcss.config.js)
   - Task 2: Base layout (app/layout.tsx, app/globals.css, app/page.tsx)  
   - Task 3: Main components (Header, Hero, main sections)
   - Task 4: Secondary components (Footer, additional sections)
   - Task 5: Data/types files if needed
3. Keep it simple - the Executor will handle the details
4. Use create_batch for new files, modify_batch for edits

Output format:
{
  "summary": "Brief human-readable summary",
  "tasks": [
    { "id": 1, "type": "create_batch", "files": ["file1.ts", "file2.ts"], "description": "Create these files" }
  ],
  "complexity": "low|medium|high"
}`;

const userMsg = 'Request: ' + ctx.message + '\n\nExisting files: None (new WebContainer project)';
let plan = null;
let messages = [{ role: 'user', content: userMsg }];

// Single iteration - fast planning
try {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': ANTHROPIC_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: JSON.stringify({ model: MODEL, max_tokens: 4096, system: SYSTEM, tools: TOOLS, messages }),
    timeout: 30000, json: true
  });

  if (r.content) {
    for (const block of r.content) {
      if (block.type === 'tool_use' && block.name === 'finish_plan') {
        plan = block.input;
        break;
      }
    }
  }
} catch (e) { 
  console.error('Planner error:', e.message); 
}

// Fallback plan with grouped tasks
if (!plan) {
  plan = { 
    summary: 'Create: ' + ctx.message, 
    tasks: [
      { id: 1, type: 'create_batch', files: ['package.json', 'tsconfig.json', 'next.config.js', 'tailwind.config.ts'], description: 'Create config files' },
      { id: 2, type: 'create_batch', files: ['app/layout.tsx', 'app/globals.css', 'app/page.tsx'], description: 'Create base app structure' }
    ], 
    complexity: 'medium',
    fallback: true 
  };
}

console.log('📋 Plan created with', plan.tasks?.length || 0, 'batched tasks');
return [{ json: { ...ctx, plan, usedPlanner: true, fileContents: {} } }];

// SIMPLE PLAN - Skip planner for simple edits
const ctx = $input.item.json;
const plan = {
  summary: ctx.message,
  tasks: [{ id: 1, type: 'modify', file: Object.keys(ctx.fileContents || {})[0] || 'src/app/page.tsx', description: ctx.message }],
  complexity: 'low'
};
console.log('⚡ Skipping planner - simple edit');
return [{ json: { ...ctx, plan, usedPlanner: false } }];

// AGENT 3: EXECUTOR (OpenRouter - Gemini 3 Flash) - WEBCONTAINER MODE
// Returns file operations as JSON for frontend to apply via WebContainers
const ctx = $input.item.json;
const requestId = ctx.requestId;
const siteUuid = ctx.site?.uuid || 'unknown';
const OPENROUTER_KEY = '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';
const MODEL = 'google/gemini-3-flash-preview';
let stepCounter = 10;

// Collect file operations for frontend to apply
let fileOperations = [];

// Thinking step helper (still writes to Supabase for real-time updates)
const emitStep = async (toolName, status, message, details = {}) => {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps',
      headers: {
        'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
        'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: JSON.stringify({
        request_id: requestId,
        site_id: siteUuid,
        step_number: stepCounter++,
        tool_name: toolName,
        status: status,
        message: message.substring(0, 200),
        details: details
      }),
      timeout: 3000
    });
  } catch(e) {}
};

await emitStep('planning', 'running', 'Creating execution plan...', { tasks: ctx.plan?.tasks?.length || 0 });

// Tools that return operations instead of executing them
const TOOLS = [
  { type: 'function', function: { name: 'list_files', description: 'List files in the project (reads from provided context)', parameters: { type: 'object', properties: { pattern: { type: 'string' } }, required: ['pattern'] } } },
  { type: 'function', function: { name: 'view_lines', description: 'View file content (reads from provided context)', parameters: { type: 'object', properties: { file: { type: 'string' }, startLine: { type: 'number' }, endLine: { type: 'number' } }, required: ['file'] } } },
  { type: 'function', function: { name: 'write_file', description: 'Create or replace entire file', parameters: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } }, required: ['path', 'content'] } } },
  { type: 'function', function: { name: 'str_replace', description: 'Replace exact text in file', parameters: { type: 'object', properties: { file: { type: 'string' }, old_text: { type: 'string' }, new_text: { type: 'string' } }, required: ['file', 'old_text', 'new_text'] } } },
  { type: 'function', function: { name: 'delete_file', description: 'Delete a file', parameters: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } } },
  { type: 'function', function: { name: 'generate_image', description: 'Generate AI image', parameters: { type: 'object', properties: { prompt: { type: 'string' }, fileName: { type: 'string' } }, required: ['prompt'] } } }
];

// Tool execution - returns JSON and collects operations
const runTool = async (name, input) => {
  // Read operations use context (from Planner's file reading)
  if (name === 'list_files') {
    await emitStep('list_files', 'running', 'Listing files: ' + (input.pattern || '*'));
    const files = Object.keys(ctx.fileContents || {});
